// @function MDQuerySetSortComparator Sets the function used to sort the results of an MDQuery. You may set the comparator function as many times as you like, even while the query is executing. Whenever the comparator function is set, all results are re-sorted using the new comparator function before the function returns. The function pointer can be NULL to cancel custom sorting and revert to the default sorting. The default sort provided by MDQueryCreate() is a assending sort strings are compared using CFStringCompare() with the options kCFCompareNonliteral | kCFCompareLocalized | kCFCompareNumerically. CFDataRefs are compared by using memcmp() of the data pointers. @param query The query to whose result sort function is to be set. @param func The callback function the MDQuery will use to sort its results. If the function (when the parameter is not NULL) is not of type MDQuerySortComparatorFunction or does not behave as a MDQuerySortComparatorFunction must, the behavior is undefined. The function pointer may be NULL to cancel any custom comparator. @param context A pointer-sized user-defined value, which is passed as the third parameter to the sort function, but is otherwise unused by MDQuery. The MDQuery does not retain the context in any way, so it must remain valid for the lifetime of the query or until the sort function is set again. If the context is not what is expected by the comparator, the behavior is undefined.
func MDQuerySetSortComparator(query unsafe.Pointer, comparator unsafe.Pointer, context_ unsafe.Pointer) {
	_fnMDQuerySetSortComparator(query, comparator, context_)
}

func MDQuerySetSortComparatorBlock(query unsafe.Pointer, comparator func(unsafe.Pointer, unsafe.Pointer) corefoundation.CFComparisonResult) {
	var __block_comparator objc.Block
	if comparator != nil {
		__block_comparator = objc.NewBlock(func(_ objc.Block, blockParam0 unsafe.Pointer, blockParam1 unsafe.Pointer) corefoundation.CFComparisonResult {
			return comparator(blockParam0, blockParam1)
		})
		defer __block_comparator.Release()
	}
	_fnMDQuerySetSortComparatorBlock(query, __block_comparator)
}

